/**
 * Offline-First Service Worker for Alchemy Pre-Test
 * Generated by WebToAPK Studio
 */

const CACHE_NAME = 'com-offline-alchemypretest-v1';
const ASSETS_TO_CACHE = [
  './',
  './index.html',
  './index.html',
  './manifest.json',
  './style.css',
  './app.js',
  './assessment.html'
];

// Install: Cache all static assets
self.addEventListener('install', (event) => {
  self.skipWaiting();
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      console.log('[Offline Engine] Pre-caching all app assets for 100% offline access');
      return cache.addAll(ASSETS_TO_CACHE).catch((err) => {
        console.warn('[Offline Engine] Asset cache warning:', err);
      });
    })
  );
});

// Activate: Clean up old caches
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => {
      return Promise.all(
        keys.map((key) => {
          if (key !== CACHE_NAME) {
            console.log('[Offline Engine] Removing old cache version:', key);
            return caches.delete(key);
          }
        })
      );
    }).then(() => self.clients.claim())
  );
});

// Fetch: 100% Offline-First Cache Strategy
self.addEventListener('fetch', (event) => {
  if (event.request.method !== 'GET') return;

  event.respondWith(
    caches.match(event.request, { ignoreSearch: true }).then((cachedResponse) => {
      if (cachedResponse) {
        return cachedResponse;
      }

      // Try network if available, fallback to index.html if offline navigation
      return fetch(event.request)
        .then((networkResponse) => {
          if (!networkResponse || networkResponse.status !== 200 || networkResponse.type !== 'basic') {
            return networkResponse;
          }
          const responseToCache = networkResponse.clone();
          caches.open(CACHE_NAME).then((cache) => {
            cache.put(event.request, responseToCache);
          });
          return networkResponse;
        })
        .catch(() => {
          if (event.request.mode === 'navigate') {
            return caches.match('./index.html') || caches.match('./');
          }
        });
    })
  );
});
